        if (trimmed.isEmpty() || trimmed.length() > displayNameMax) {
            throw ValidationException.of(422, "display name must be 1-" + displayNameMax + " characters");
        }
        Account updated = account.withDisplayName(trimmed);
        accounts.save(updated);
        return updated;
    }

